import { APP_KEY_PLAN_PREFIXES } from 'src/constants';

export type Tier = 'LIGHT' | 'MEDIUM' | 'LARGE';

export const TIER_DEFAULTS: Record<
  Tier,
  { icon: string; recommended: boolean }
> = {
  LIGHT: { icon: 'bolt', recommended: false },
  MEDIUM: { icon: 'auto_awesome', recommended: true },
  LARGE: { icon: 'rocket_launch', recommended: false },
};

export function getPlanPrefixes(appKey: string): string[] {
  return APP_KEY_PLAN_PREFIXES[appKey] || [appKey];
}

const SANDBOX_KEY_PATTERN = /(?:^|_)SANDBOX(?:_|$)/;

export function isSandboxPlanKey(planKey: string | null | undefined): boolean {
  if (!planKey) return false;
  return SANDBOX_KEY_PATTERN.test(planKey.toUpperCase());
}

/**
 * Narrows plans to the ones sellable in the active environment.
 *
 *  - Non-Sandbox env → drop every `_SANDBOX` plan. A customer must never buy a
 *    Sandbox plan in PRD, so this stays a hard exclusion.
 *  - Sandbox env → PREFER `_SANDBOX` plans: with at least one present, keep only
 *    those plus anything already active. With none — several products ship a
 *    single SKU and no sandbox tier — keep the regular plans, since excluding
 *    them left nothing selectable and no way to subscribe or re-activate.
 */
export function filterPlansByEnvironment<T extends { key?: string | null }>(
  plans: T[],
  isSandbox: boolean,
  activePlanKeys: Iterable<string> = [],
): T[] {
  if (!isSandbox) {
    return plans.filter((plan) => !isSandboxPlanKey(plan.key));
  }
  const hasSandboxPlan = plans.some((plan) => isSandboxPlanKey(plan.key));
  if (hasSandboxPlan) {
    const active = new Set(
      Array.from(activePlanKeys, (key) => key.toUpperCase()),
    );
    return plans.filter(
      (plan) =>
        isSandboxPlanKey(plan.key) ||
        (!!plan.key && active.has(plan.key.toUpperCase())),
    );
  }
  return plans;
}

/**
 * Extract the trailing numeric magnitude from a plan key
 * (e.g. "FOO_BAR_5000" or "FOO_BAR_5000_SANDBOX" → 5000). Returns null when
 * the key has no numeric segment — these sort ahead of numbered tiers.
 */
function planTierMagnitude(planKey: string | null | undefined): number | null {
  if (!planKey) return null;
  const match = planKey.toUpperCase().match(/_(\d+)(?:_[A-Z]+)?$/);
  return match ? Number(match[1]) : null;
}

/**
 * Order plans for a combined dialog that mixes two related app keys:
 * plans for `primaryAppKey` (entry-level) come first, plans for
 * `tieredAppKey` (upgrade tiers) follow, each group sorted ascending by
 * the plan's trailing numeric magnitude. Stable for plans that match
 * neither key (kept in input order via Array.sort stability).
 */
export function compareCombinedPlans<T extends { key?: string | null }>(
  primaryAppKey: string,
  tieredAppKey: string,
): (a: T, b: T) => number {
  return (a, b) => {
    const aPrimary = isSubscriptionForThisApp(a.key, primaryAppKey);
    const bPrimary = isSubscriptionForThisApp(b.key, primaryAppKey);
    if (aPrimary && !bPrimary) return -1;
    if (!aPrimary && bPrimary) return 1;
    const aTiered = isSubscriptionForThisApp(a.key, tieredAppKey);
    const bTiered = isSubscriptionForThisApp(b.key, tieredAppKey);
    if (aTiered && !bTiered) return -1;
    if (!aTiered && bTiered) return 1;
    return (planTierMagnitude(a.key) ?? -1) - (planTierMagnitude(b.key) ?? -1);
  };
}

/**
 * Pick the cheapest plan from the list belonging to `appKey`. Returns null
 * when nothing matches. Used by callers that need to auto-subscribe an org
 * to a companion plan derived from the current plan list.
 */
export function findCheapestPlanForApp<
  T extends { key?: string | null; price?: string | number | null },
>(plans: T[], appKey: string): T | null {
  const matching = plans.filter((p) => isSubscriptionForThisApp(p.key, appKey));
  if (matching.length === 0) return null;
  const toNumber = (value: string | number | null | undefined): number => {
    // Treat missing or non-numeric prices as +Infinity so they sort last,
    // never beating a real-priced sibling. Number(null) and Number('') both
    // coerce to 0, which would otherwise win the sort incorrectly.
    if (value === null || value === undefined || value === '') {
      return Number.POSITIVE_INFINITY;
    }
    const n = typeof value === 'number' ? value : Number(value);
    return Number.isFinite(n) ? n : Number.POSITIVE_INFINITY;
  };
  return [...matching].sort(
    (a, b) => toNumber(a.price) - toNumber(b.price),
  )[0] ?? null;
}

export function getTierKey(planKey: string | null | undefined): Tier | null {
  if (!planKey) return null;
  const upper = planKey.toUpperCase();
  if (upper.endsWith('_LIGHT')) return 'LIGHT';
  if (upper.endsWith('_MEDIUM')) return 'MEDIUM';
  if (upper.endsWith('_LARGE')) return 'LARGE';
  return null;
}

/**
 * Returns true when the given subscription `plan_key` belongs to the app
 * identified by `appKey` — via direct match or prefix-and-underscore match.
 */
export function isSubscriptionForThisApp(
  planKey: string | null | undefined,
  appKey: string,
): boolean {
  if (!planKey) return false;
  if (planKey === appKey) return true;
  const prefixes = getPlanPrefixes(appKey);
  return prefixes.some(
    (prefix) => planKey === prefix || planKey.startsWith(prefix + '_'),
  );
}

/**
 * A plan is blocked in the dialog when another plan for the same app is
 * already active — e.g. org has OPERATOR_LIGHT, so OPERATOR_MEDIUM is blocked.
 * The currently active plan itself is NOT blocked.
 */
export function isPlanBlocked(
  plan: { id: string },
  activePlanIds: Set<string>,
  activePlanKeys: Set<string>,
  appKey: string,
): boolean {
  if (activePlanIds.has(plan.id)) return false;
  if (activePlanKeys.size === 0) return false;
  for (const activeKey of activePlanKeys) {
    if (isSubscriptionForThisApp(activeKey, appKey)) return true;
  }
  return false;
}

/**
 * True when a subscription-create error means the org ALREADY has an active
 * subscription for the app being enabled.
 *
 * The backend (DocBits_Auth) matches conflicting subscriptions by APP, while
 * this dialog only detects an existing subscription by plan-key prefix. When
 * the org holds the app via a plan whose key the prefix map doesn't recognise
 * (a bundle, or a plan renamed by a price-list realignment), the create call
 * fails with "Organisation already has an active subscription using <app>".
 * Since the create was for this module's own app, that conflict is idempotent:
 * the module should be enabled rather than left stuck with the toggle off.
 */
export function isAlreadySubscribedConflict(error: unknown): boolean {
  const re = /already has an active subscription/i;
  const seen = new Set<unknown>();
  const stack: unknown[] = [error];
  while (stack.length) {
    const cur = stack.pop();
    if (cur == null || seen.has(cur)) continue;
    seen.add(cur);
    if (typeof cur === 'string') {
      if (re.test(cur)) return true;
      continue;
    }
    if (typeof cur === 'object') {
      // ApiErrorMessage is a String object; coerce and test its text too.
      const text = String(cur);
      if (text && text !== '[object Object]' && re.test(text)) return true;
      const o = cur as Record<string, unknown>;
      for (const k of [
        'message',
        'detail',
        'fullDetail',
        'data',
        'response',
        'error',
        'msg',
      ]) {
        if (k in o) stack.push(o[k]);
      }
    }
  }
  return false;
}

interface SubscriptionLike {
  plan_key?: string | null;
  apps?: ({ app_key?: string | null } | null)[] | null;
}

/**
 * True when a subscription belongs to the given app.
 *
 * Primary signal: the SDK's authoritative `apps[].app_key` — the SAME app
 * identity the backend uses to detect conflicts. This is what keeps the
 * frontend and backend in agreement.
 *
 * Fallback: the legacy plan-key prefix match, for subscriptions whose `apps[]`
 * array isn't populated. Relying on the plan key ALONE is what caused the
 * incident: a price-list realignment renamed plans, the prefix map drifted, and
 * the dialog stopped recognising an org's active subscription — so it tried to
 * create a duplicate the backend then rejected. Matching on `app_key` makes
 * that drift impossible.
 */
export function subscriptionMatchesApp(
  sub: SubscriptionLike | null | undefined,
  appKey: string,
): boolean {
  if (!sub) return false;
  const byApp = (sub.apps ?? []).some(
    (a) => a != null && a.app_key != null && a.app_key === appKey,
  );
  if (byApp) return true;
  return isSubscriptionForThisApp(sub.plan_key, appKey);
}
